// ===== 1. Procesamiento de la información =====
// El webhook de n8n entrega el payload bajo "body" (headers, query, body).
const input = $input.item.json || {};
const payload = input.body && typeof input.body === 'object' ? input.body : input;
const data = payload.data || {};
const stock = (data.stock_bajo || []).map((s) =>
  `- ${s.insumo} en ${s.ubicacion}: ${s.cantidad} uds (mínimo ${s.minimo})`
);
const mermas = (data.mermas || []).map((m) =>
  `- ${m.insumo}: ${m.cantidad} uds (${m.motivo})`
);
const minibar = (data.minibar_pendiente || []).length;

const resumen = data.resumen || {};

const textoPlano = [
  `Reporte de operación — ${data.generated_at || new Date().toISOString()}`,
  `Ítems con stock bajo/crítico: ${resumen.items_stock_bajo ?? stock.length}`,
  `Mermas registradas: ${resumen.mermas_ultimas ?? mermas.length}`,
  `Consumos de minibar pendientes de cobro: ${minibar}`,
  '',
  '=== STOCK BAJO / CRÍTICO ===',
  stock.length ? stock.join('\n') : 'Sin incidencias de stock.',
  '',
  '=== MERMAS ===',
  mermas.length ? mermas.join('\n') : 'Sin mermas registradas.',
].join('\n');

return [{ json: { ...$input.item.json, resumen_plano: textoPlano } }];

// ===== 2. Preparar la llamada a Gemini =====
// Construye el prompt y serializa el body de la API (sin depender de fetch).

const resumen_plano = $input.item.json.resumen_plano || '';
const prompt = 'Eres un analista hotelero. Resume el siguiente reporte de inventario y destaca los 3 riesgos más urgentes de fuga o desperdicio. Sé concreto:\n\n' + resumen_plano;

const body = JSON.stringify({
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.2 },
});

return [{ json: { prompt, body, resumen_plano } }];

// ===== 2c. Normalizar la respuesta de Gemini =====
const raw = $input.item.json;
const prepared = $('2. Preparar llamada IA').first().json;

let data = raw;
if (typeof raw === 'string') {
  try {
    data = JSON.parse(raw);
  } catch (e) {
    data = { error: 'No se pudo interpretar la respuesta: ' + String(raw).slice(0, 200) };
  }
}
if (data && typeof data === 'object' && !data.candidates && data.error) {
  data = { error: String(data.error).slice(0, 400) };
}
if (data && typeof data === 'object') {
  data.resumen_plano = prepared.resumen_plano || '';
  const analysis = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const escapeHtml = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  data.analysis_html = escapeHtml(analysis)
    .replace(/^### (.*)$/gm, '<h3>$1</h3>')
    .replace(/^## (.*)$/gm, '<h2>$1</h2>')
    .replace(/^---$/gm, '<hr>')
    .replace(/^[-*] (.*)$/gm, '<li>$1</li>')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\n\n/g, '<br><br>')
    .replace(/\n/g, '<br>');
}

return [{ json: data }];
